license     = "MIT"
readme      = "README.md"
repository  = "https://github.com/your-org/cisak"
homepage    = "https://github.com/your-org/cisak"
keywords    = ["container", "runc", "cni", "containerd", "installer"]
categories  = ["command-line-utilities", "development-tools"]
exclude     = [".dump", ".git"]

[[bin]]
name = "cisak"
path = "src/main.rs"

[dependencies]
clap     = { version = "4", features = ["derive"] }
serde    = { version = "1", features = ["derive"] }
toml     = "1.1.2"
anyhow   = "1"
tempfile = "3"
