### `src/main.rs`

```rust
mod config;
mod install;
mod runner;

use anyhow::Result;
use clap::{Parser, Subcommand};

/// Container Installation – Swiss Army Knife
///
/// Downloads, verifies, and installs runc, CNI plugins, and containerd
/// from their official GitHub releases.
#[derive(Parser)]
#[command(name = "cisak", version, propagate_version = true)]
struct Cli {
    /// Skip all y/N confirmations (assume yes)
    #[arg(short = 'y', long, global = true)]
    assume_yes: bool,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Generate a config.toml scaffold in the current directory
    Generate,
    /// Download, verify, and install runc + CNI plugins + containerd
    Run,
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Generate => install::generate_config(),
        Commands::Run => install::run(cli.assume_yes),
    }
}
```

