use anyhow::{Context, Result};
use serde::Deserialize;

/// Top-level configuration (read from `config.toml`).
#[derive(Deserialize)]
pub struct Config {
    pub runtime: RuntimeConfig,
    pub cni: Option<CniConfig>,
    pub containerd: Option<ContainerdConfig>,
}

impl Config {
    /// Read and parse `config.toml` from the current working directory.
    pub fn load() -> Result<Self> {
        let raw = std::fs::read_to_string("config.toml")
            .context("could not read config.toml in the current directory")?;
        toml::from_str(&raw).context("failed to parse config.toml")
    }
}

// ─── runc ────────────────────────────────────────────────────────────────────

#[derive(Deserialize)]
pub struct RuntimeConfig {
    /// Informational name (e.g. `"runc"`).
    pub name: String,
    /// Release tag, e.g. `"v1.4.2"`.
    pub version: String,
    /// Destination path for the installed binary.
    pub binary: Option<String>,
}

impl RuntimeConfig {
    pub fn binary_path(&self) -> &str {
        self.binary.as_deref().unwrap_or("/usr/local/sbin/runc")
    }
}

// ─── CNI plugins ─────────────────────────────────────────────────────────────

#[derive(Deserialize)]
pub struct CniConfig {
    /// Release tag, e.g. `"v1.9.1"`.
    pub version: String,
    /// Directory the tarball is extracted into.
    pub install_dir: Option<String>,
}

impl CniConfig {
    pub fn dir(&self) -> &str {
        self.install_dir.as_deref().unwrap_or("/opt/cni/bin")
    }
}

// ─── containerd ──────────────────────────────────────────────────────────────

#[derive(Deserialize)]
pub struct ContainerdConfig {
    /// Release tag, e.g. `"v2.2.3"`.
    pub version: String,
    /// Installation prefix; binaries land in `<prefix>/bin/`.
    pub install_dir: Option<String>,
}

impl ContainerdConfig {
    pub fn prefix(&self) -> &str {
        self.install_dir.as_deref().unwrap_or("/usr/local")
    }
}
