### `src/runner.rs`

```rust
use anyhow::{bail, Context, Result};
use std::io::{self, Write};
use std::path::Path;
use std::process::Command;

/// Wraps external-command execution with display, optional confirmation,
/// and automatic sudo retry on failure.
pub struct Runner {
    pub assume_yes: bool,
}

impl Runner {
    pub fn new(assume_yes: bool) -> Self {
        Self { assume_yes }
    }

    // ── public API ────────────────────────────────────────────────────────────

    /// Show `args`, optionally confirm, run from the current directory.
    /// On non-zero exit the command is retried once with `sudo` prepended.
    pub fn run(&self, args: &[&str]) -> Result<()> {
        self.exec(args, None)
    }

    /// Like [`run`] but executes the command from `cwd`.
    pub fn run_in(&self, args: &[&str], cwd: &Path) -> Result<()> {
        self.exec(args, Some(cwd))
    }

    // ── private helpers ───────────────────────────────────────────────────────

    fn exec(&self, args: &[&str], cwd: Option<&Path>) -> Result<()> {
        Self::print_cmd(args, /* sudo_prefix = */ false);
        self.confirm()?;

        let status = Self::spawn(args, cwd)
            .with_context(|| format!("failed to spawn `{}`", args[0]))?;

        if status.success() {
            return Ok(());
        }

        // ── sudo retry ────────────────────────────────────────────────────────
        eprintln!(
            "\n  \x1b[33m⚠\x1b[0m  `{}` exited with code {} — retrying with sudo",
            args[0],
            status.code().unwrap_or(-1)
        );

        let mut sudo_args = vec!["sudo"];
        sudo_args.extend_from_slice(args);

        Self::print_cmd(&sudo_args, true);
        self.confirm()?;

        let status = Self::spawn(&sudo_args, cwd)
            .with_context(|| format!("failed to spawn `sudo {}`", args[0]))?;

        if !status.success() {
            bail!(
                "`sudo {}` exited with code {:?}",
                args[0],
                status.code()
            );
        }

        Ok(())
    }

    /// Spawn `args` (optionally in `cwd`) and return the exit status.
    fn spawn(args: &[&str], cwd: Option<&Path>) -> Result<std::process::ExitStatus> {
        let mut cmd = Command::new(args[0]);
        cmd.args(&args[1..]);
        if let Some(dir) = cwd {
            cmd.current_dir(dir);
        }
        cmd.status().context("OS-level spawn failure")
    }

    fn print_cmd(args: &[&str], is_sudo: bool) {
        let color = if is_sudo { "\x1b[33m" } else { "\x1b[32m" };
        println!("\n  {color}$\x1b[0m  {}", args.join(" "));
    }

    fn confirm(&self) -> Result<()> {
        if self.assume_yes {
            return Ok(());
        }
        print!("  Run? [y/N] ");
        io::stdout().flush()?;
        let mut buf = String::new();
        io::stdin().read_line(&mut buf)?;
        if !buf.trim().eq_ignore_ascii_case("y") {
            bail!("aborted by user");
        }
        Ok(())
    }
}
