### `src/install.rs`

```rust
use anyhow::{bail, Context, Result};
use std::fs;
use std::path::Path;
use std::process::Command;
use tempfile::TempDir;

use crate::config::{CniConfig, Config, ContainerdConfig, RuntimeConfig};
use crate::runner::Runner;

// ─── config scaffold ─────────────────────────────────────────────────────────

const CONFIG_TEMPLATE: &str = r#"# Generated by cisak — edit version fields as needed, then run `cisak run`.

[runtime]
name    = "runc"
version = "v1.4.2"
binary  = "/usr/local/sbin/runc"   # optional — default shown

[cni]
version     = "v1.9.1"
install_dir = "/opt/cni/bin"       # optional — default shown

[containerd]
# Binaries land in <install_dir>/bin/ (e.g. /usr/local/bin/containerd)
version     = "v2.2.3"
install_dir = "/usr/local"         # optional — default shown
"#;

/// Write a `config.toml` scaffold to the current directory.
pub fn generate_config() -> Result<()> {
    let path = Path::new("config.toml");
    if path.exists() {
        bail!("config.toml already exists in the current directory — refusing to overwrite");
    }
    fs::write(path, CONFIG_TEMPLATE).context("failed to write config.toml")?;
    println!("Wrote config.toml — edit version fields as needed, then run `cisak run`.");
    Ok(())
}

// ─── orchestrator ─────────────────────────────────────────────────────────────

/// Read `config.toml` and install each configured component.
pub fn run(assume_yes: bool) -> Result<()> {
    let cfg = Config::load()?;
    let runner = Runner::new(assume_yes);
    let tmp = TempDir::new().context("could not create temporary directory")?;

    section("runc");
    install_runc(&cfg.runtime, &runner, tmp.path())?;

    if let Some(cni) = &cfg.cni {
        section("CNI plugins");
        install_cni(cni, &runner, tmp.path())?;
    }

    if let Some(ct) = &cfg.containerd {
        section("containerd");
        install_containerd(ct, &runner, tmp.path())?;
    }

    println!("\n\x1b[1;32m✔  All done.\x1b[0m\n");
    Ok(())
}

fn section(name: &str) {
    println!(
        "\n\x1b[1m── {name} {}\x1b[0m",
        "─".repeat(70_usize.saturating_sub(name.len() + 4))
    );
}

// ─── runc ────────────────────────────────────────────────────────────────────

/// Full GPG fingerprint for Aleksa Sarai's release-signing key.
const RUNC_GPG_FINGERPRINT: &str = "C2428CD7CA99FA6C7A9DCEDA7D6BCE14EBE1B0D0";
const RUNC_KEYSERVER: &str = "hkps://keyserver.ubuntu.com";
const RUNC_BASE: &str = "https://github.com/opencontainers/runc/releases/download";

fn install_runc(cfg: &RuntimeConfig, runner: &Runner, tmp: &Path) -> Result<()> {
    let ver = &cfg.version;
    let dest = cfg.binary_path();

    let binary_path = tmp.join("runc.amd64");
    let sig_path = tmp.join("runc.amd64.asc");

    let binary_str = binary_path.to_str().unwrap();
    let sig_str = sig_path.to_str().unwrap();

    // 1. Import GPG key (if not already present)
    ensure_gpg_key(RUNC_GPG_FINGERPRINT, RUNC_KEYSERVER, runner)?;

    // 2. Download binary
    runner.run(&[
        "curl", "-fsSL", "-o", binary_str,
        &format!("{RUNC_BASE}/{ver}/runc.amd64"),
    ])?;

    // 3. Download detached signature
    runner.run(&[
        "curl", "-fsSL", "-o", sig_str,
        &format!("{RUNC_BASE}/{ver}/runc.amd64.asc"),
    ])?;

    // 4. Verify signature
    runner.run(&["gpg", "--verify", sig_str, binary_str])?;

    // 5. Install (retries with sudo if needed)
    runner.run(&["install", "-m", "0755", binary_str, dest])?;

    println!("\n  \x1b[32m✔\x1b[0m  runc {ver} → {dest}");
    Ok(())
}

/// Import `fingerprint` from `keyserver` unless it is already in the local keyring.
fn ensure_gpg_key(fingerprint: &str, keyserver: &str, runner: &Runner) -> Result<()> {
    let already_present = Command::new("gpg")
        .args(["--list-keys", fingerprint])
        .output()
        .context("failed to run `gpg --list-keys`")?
        .status
        .success();

    if already_present {
        println!("\n  GPG key {fingerprint} already in local keyring.");
        return Ok(());
    }

    println!("\n  GPG key {fingerprint} not found — importing from {keyserver}");
    runner.run(&[
        "gpg",
        "--keyserver", keyserver,
        "--recv-keys", fingerprint,
    ])
}

// ─── CNI plugins ─────────────────────────────────────────────────────────────

const CNI_BASE: &str =
    "https://github.com/containernetworking/plugins/releases/download";

fn install_cni(cfg: &CniConfig, runner: &Runner, tmp: &Path) -> Result<()> {
    let ver = &cfg.version;
    let dir = cfg.dir();

    // GitHub filenames include the version tag (with leading 'v').
    let archive_name = format!("cni-plugins-linux-amd64-{ver}.tgz");
    let sha_name = format!("cni-plugins-linux-amd64-{ver}.tgz.sha512");

    let archive_path = tmp.join(&archive_name);
    let sha_path = tmp.join(&sha_name);

    // 1. Download archive
    runner.run(&[
        "curl", "-fsSL", "-o", archive_path.to_str().unwrap(),
        &format!("{CNI_BASE}/{ver}/{archive_name}"),
    ])?;

    // 2. Download SHA-512 checksum file
    runner.run(&[
        "curl", "-fsSL", "-o", sha_path.to_str().unwrap(),
        &format!("{CNI_BASE}/{ver}/{sha_name}"),
    ])?;

    // 3. Verify checksum (run from tmp so the relative path in the file resolves)
    runner.run_in(&["sha512sum", "--check", &sha_name], tmp)?;

    // 4. Create destination directory
    runner.run(&["mkdir", "-p", dir])?;

    // 5. Extract (retries with sudo if needed)
    runner.run(&[
        "tar", "-C", dir, "-xzf", archive_path.to_str().unwrap(),
    ])?;

    println!("\n  \x1b[32m✔\x1b[0m  CNI plugins {ver} → {dir}");
    Ok(())
}

// ─── containerd ──────────────────────────────────────────────────────────────

const CONTAINERD_BASE: &str =
    "https://github.com/containerd/containerd/releases/download";

fn install_containerd(cfg: &ContainerdConfig, runner: &Runner, tmp: &Path) -> Result<()> {
    let ver = &cfg.version;
    let prefix = cfg.prefix();

    // Filenames use the bare version (no leading 'v'); the URL tag keeps 'v'.
    let ver_bare = ver.trim_start_matches('v');
    let ver_tag = if ver.starts_with('v') {
        ver.as_str()
    } else {
        // Defensive: add 'v' if the user omitted it.
        // We shadow with a local String to extend its lifetime.
        ver.as_str() // handled below
    };

    let archive_name = format!("containerd-{ver_bare}-linux-amd64.tar.gz");
    let sha_name = format!("containerd-{ver_bare}-linux-amd64.tar.gz.sha256sum");

    let archive_path = tmp.join(&archive_name);
    let sha_path = tmp.join(&sha_name);

    let url_base = if ver.starts_with('v') {
        format!("{CONTAINERD_BASE}/{ver}")
    } else {
        format!("{CONTAINERD_BASE}/v{ver}")
    };

    // 1. Download archive
    runner.run(&[
        "curl", "-fsSL", "-o", archive_path.to_str().unwrap(),
        &format!("{url_base}/{archive_name}"),
    ])?;

    // 2. Download SHA-256 checksum file
    runner.run(&[
        "curl", "-fsSL", "-o", sha_path.to_str().unwrap(),
        &format!("{url_base}/{sha_name}"),
    ])?;

    // 3. Verify checksum (run from tmp so relative paths resolve)
    runner.run_in(&["sha256sum", "--check", &sha_name], tmp)?;

    // 4. Create destination directory
    runner.run(&["mkdir", "-p", &format!("{prefix}/bin")])?;

    // 5. Extract (retries with sudo if needed)
    runner.run(&[
        "tar", "-C", prefix, "-xzf", archive_path.to_str().unwrap(),
    ])?;

    let _ = ver_tag; // silence unused-variable warning from the if/else above
    println!("\n  \x1b[32m✔\x1b[0m  containerd {ver} → {prefix}/bin/");
    Ok(())
}
